// Nodo de publicacion en Facebook Page + Instagram Business con soporte de reintento parcial
const body = $input.first().json.body || $input.first().json;

const pageId = $env.META_PAGE_ID;
const igUserId = $env.META_IG_USER_ID;
const accessToken = $env.META_PAGE_ACCESS_TOKEN;

let fbPostId = body.prev_fb_post_id || null;
let igMediaId = body.prev_ig_media_id || null;
const errors = [];

const fotos = Array.isArray(body.fotos) ? body.fotos.filter(Boolean) : [];
const mapImageUrl = body.mapa_zona_url || null;
const allMedia = mapImageUrl ? [...fotos.slice(0, 9), mapImageUrl] : fotos.slice(0, 10);

const fbCaption = `${body.texto_post}\n\n🗺️ Ver zona en el mapa: ${body.url_mapa}`;
const igCaption = `${body.texto_post}\n\n🔗 Encuentra el mapa interactivo en el enlace de nuestra biografía.`;

if (!accessToken) {
  errors.push('Falta configurar META_PAGE_ACCESS_TOKEN en las variables de entorno de n8n');
} else if (fotos.length === 0) {
  errors.push('El inmueble no tiene URLs de fotos públicas para publicar');
} else {
  // 1. Publicar en Facebook Page (solo si no fue publicado previamente en un intento anterior)
  if (pageId && !fbPostId) {
    try {
      const attachedMedia = [];
      for (const photoUrl of allMedia.slice(0, 6)) {
        const mediaRes = await this.helpers.httpRequest({
          method: 'POST',
          url: `https://graph.facebook.com/v21.0/${pageId}/photos`,
          body: {
            url: photoUrl,
            published: false,
            access_token: accessToken,
          },
          json: true,
        });
        if (mediaRes && mediaRes.id) {
          attachedMedia.push({ media_fbid: mediaRes.id });
        }
      }

      const feedRes = await this.helpers.httpRequest({
        method: 'POST',
        url: `https://graph.facebook.com/v21.0/${pageId}/feed`,
        body: {
          message: fbCaption,
          attached_media: attachedMedia,
          access_token: accessToken,
        },
        json: true,
      });

      fbPostId = feedRes.id || null;
    } catch (err) {
      errors.push(`Facebook Error: ${err.message || String(err)}`);
    }
  }

  // 2. Publicar en Instagram Business (1 foto directa o Carrusel hasta 10 elementos)
  if (igUserId && !igMediaId) {
    try {
      let creationId = null;
      if (allMedia.length === 1) {
        const singleContainer = await this.helpers.httpRequest({
          method: 'POST',
          url: `https://graph.facebook.com/v21.0/${igUserId}/media`,
          body: {
            image_url: allMedia[0],
            caption: igCaption,
            access_token: accessToken,
          },
          json: true,
        });
        creationId = singleContainer.id;
      } else {
        const childrenIds = [];
        for (const imgUrl of allMedia.slice(0, 10)) {
          const itemContainer = await this.helpers.httpRequest({
            method: 'POST',
            url: `https://graph.facebook.com/v21.0/${igUserId}/media`,
            body: {
              image_url: imgUrl,
              is_carousel_item: true,
              access_token: accessToken,
            },
            json: true,
          });
          if (itemContainer && itemContainer.id) {
            childrenIds.push(itemContainer.id);
          }
        }

        const carouselContainer = await this.helpers.httpRequest({
          method: 'POST',
          url: `https://graph.facebook.com/v21.0/${igUserId}/media`,
          body: {
            media_type: 'CAROUSEL',
            children: childrenIds.join(','),
            caption: igCaption,
            access_token: accessToken,
          },
          json: true,
        });
        creationId = carouselContainer.id;
      }

      if (creationId) {
        const publishRes = await this.helpers.httpRequest({
          method: 'POST',
          url: `https://graph.facebook.com/v21.0/${igUserId}/media_publish`,
          body: {
            creation_id: creationId,
            access_token: accessToken,
          },
          json: true,
        });
        igMediaId = publishRes.id || null;
      }
    } catch (err) {
      errors.push(`Instagram Error: ${err.message || String(err)}`);
    }
  }
}

return [
  {
    json: {
      callback_url: body.callback_url,
      payload: {
        difusion_id: body.difusion_id,
        estado: errors.length > 0 ? 'error' : 'publicado',
        fb_post_id: fbPostId,
        ig_media_id: igMediaId,
        error: errors.length > 0 ? errors.join(' | ') : null,
      },
    },
  },
];
